mapper.select:
select ir.*, e.name as enterprise_name, e.description as industry, e.employee_scale, cn.name as node_name, nd.diagnosis_tag from investment_recommendation ir left join enterprise e on ir.enterprise_id = e.id left join chain_node cn on ir.target_node_id = cn.id left join node_diagnosis nd on cn.id = nd.node_id and nd.is_deleted = 0 and nd.id = (select max(n2.id) from node_diagnosis n2 where n2.node_id = cn.id and n2.is_deleted = 0)
ir.is_deleted = 0 and e.is_local = 0 and ir.business_fit_score > 0 and ir.region_id = #{regionId} and nd.diagnosis_tag = #{weakness} and ir.total_score >= #{matchMin} and e.employee_scale = #{scale} and e.name like concat('%', #{keyword}, '%') and ir.target_node_id = #{nodeId}
order by ir.business_fit_score desc order by ir.scale_strength_score desc order by ir.regional_synergy_score desc order by ir.total_score desc
limit #{offset}, #{limit}

select count(*)
from investment_recommendation ir
left join enterprise e on ir.enterprise_id = e.id
left join chain_node cn on ir.target_node_id = cn.id
left join node_diagnosis nd on cn.id = nd.node_id
    and nd.is_deleted = 0
    and nd.id = (select max(n2.id) from node_diagnosis n2
                 where n2.node_id = cn.id and n2.is_deleted = 0)

    ir.is_deleted = 0 and e.is_local = 0 and ir.business_fit_score > 0
    and ir.region_id = #{regionId}
    and nd.diagnosis_tag = #{weakness}
    and ir.total_score >= #{matchMin}
    and e.employee_scale = #{scale}
    and e.name like concat('%', #{keyword}, '%')
    and ir.target_node_id = #{nodeId}

select count(*) from investment_recommendation
where enterprise_id = #{enterpriseId}
and target_node_id = #{nodeId}
and status = 'wishlist'
and is_deleted = 0

mapper.update:
update investment_recommendation
set status = 'wishlist', updated_at = now()
where enterprise_id = #{enterpriseId}
and target_node_id = #{nodeId}

update investment_recommendation
set status = 'pending', updated_at = now()
where id = #{id}

update investment_recommendation
business_fit_score = #{businessFitScore}, scale_strength_score = #{scaleStrengthScore}, regional_synergy_score = #{regionalSynergyScore}, total_score = #{totalScore}, rating = #{rating}, match_reasons = #{matchReasons}, demand_province = #{demandProvince}, status = #{status},
where id = #{id}
